using System;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
using Kamilunavo.RepairEmpire.Core;
using Kamilunavo.RepairEmpire.Gameplay;
using Kamilunavo.RepairEmpire.UI;
using Kamilunavo.RepairEmpire.Input;
public static class RepairHudRegression
{
 static readonly BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;static int checks;static List<string> failures;
 static void Check(bool valid,string label){checks++;if(!valid&&failures.Count<90)failures.Add(label);}
 static void Invoke(RepairHud hud,string method)=>typeof(RepairHud).GetMethod(method,Private).Invoke(hud,null);
 static RectTransform Modal(RepairHud hud)=>(RectTransform)typeof(RepairHud).GetField("modal",Private).GetValue(hud);
 static string TextAt(Transform root,string path)=>root.Find(path)?.GetComponent<Text>()?.text??"";
 public static void Validate(){checks=0;failures=new List<string>();try{foreach(string lang in new[]{"de","en"})foreach(var pane in new[]{new Vector2(375,627),new Vector2(734,343),new Vector2(190,627)})Fixture(lang,pane);}finally{UiMetrics.QaPointScale=null;}if(failures.Count>0)throw new InvalidOperationException("REPAIR_HUD_REGRESSION: "+string.Join("; ",failures));Debug.Log("REPAIR_HUD_REGRESSION_PASS checks="+checks);}
 static void Fixture(string language,Vector2 pane){var root=new GameObject("RepairHudFixture");root.SetActive(false);var canvasGo=new GameObject("RepairHudCanvas",typeof(Canvas));try{
  var canvas=canvasGo.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.scaleFactor=3;UiMetrics.QaPointScale=3;var region=new GameObject("SafePane",typeof(RectTransform)).GetComponent<RectTransform>();region.SetParent(canvas.transform,false);region.anchorMin=region.anchorMax=Vector2.one*.5f;region.sizeDelta=pane;
  var game=root.AddComponent<RepairGame>();game.Profile=new RepairProfile{Language=language,Level=8,Cash=2345,ToolMask=7,Style=2};var hud=root.AddComponent<RepairHud>();hud.Build(region,game);hud.ShowDashboard();hud.ShowPage(1);var modal=Modal(hud);var content=modal.Find("PageBody/ScrollViewport/ScrollContent");var icons=new HashSet<string>();foreach(string item in new[]{"Tool0","Tool1","Tool2","FleetShortcut"})icons.Add(IconSignature(content.Find(item)));Check(icons.Count==4,language+pane+" wrench/tester/toolkit/fleet have distinct geometry");
  hud.ShowPage(3);modal=Modal(hud);content=modal.Find("PageBody/ScrollViewport/ScrollContent");icons.Clear();foreach(string item in new[]{"Workshop","Headquarters","Paint0","Paint1","Paint2","Paint3"})icons.Add(IconSignature(content.Find(item)));Check(icons.Count==6,language+pane+" upgrade/HQ/paint show matching distinct previews");
  hud.ShowPage(6);modal=Modal(hud);var back=modal.Find("MenuBack");Check(back!=null,language+pane+" child screen provides previous-menu Back");if(back!=null){game.NativePresenting=()=>true;back.GetComponent<Button>().onClick.Invoke();Check(TextAt(Modal(hud),"SectionTitle")==game.T("Optionen","Options")&&game.TabletOpen,language+pane+" native presenter blocks Back and keeps pause");game.NativePresenting=()=>false;game.Profile.Language=language=="de"?"en":"de";hud.Layout();region.sizeDelta=new Vector2(pane.y,pane.x);hud.Layout();Modal(hud).Find("MenuBack").GetComponent<Button>().onClick.Invoke();Check(TextAt(Modal(hud),"SectionTitle")==game.T("Werkstatt","Workshop")&&game.TabletOpen&&game.Paused,language+pane+" Back retains workshop parent across locale/orientation refresh");region.sizeDelta=pane;game.Profile.Language=language;hud.Layout();}
  typeof(RepairGame).GetField("<RepairOpen>k__BackingField",Private).SetValue(game,true);
  int jobs=pane.x==375?game.Jobs.Count:4;for(int index=0;index<jobs;index++){var job=game.Jobs[index];game.Profile.ActiveJob=job.Id;for(int phase=0;phase<3;phase++){game.Profile.RepairPhase=phase;game.Interaction=new RepairInteraction(phase,1,job.Presentation);hud.RefreshProfile();modal=Modal(hud);CheckFixedTargets(modal,pane);var stage=job.Presentation.Stages[phase];content=modal.Find("PageBody/ScrollViewport/ScrollContent");Check(TextAt(content,"Stage")==game.T(stage.TitleDe,stage.TitleEn),job.Id+" phase"+phase+" exact localized stage "+language);Check(TextAt(content,"Instructions")==game.T(stage.InstructionDe,stage.InstructionEn),job.Id+" phase"+phase+" exact localized instruction "+language);var shelf=modal.Find("RepairActionShelf");int actions=0;foreach(var button in shelf.GetComponentsInChildren<Button>())if(button.name.StartsWith("RepairTap")){actions++;int number=int.Parse(button.name.Substring(9));Check(number<stage.Actions.Length&&button.GetComponentInChildren<Text>().text.Contains(game.T(stage.Actions[number].LabelDe,stage.Actions[number].LabelEn)),job.Id+" contextual action label "+phase);}Check(stage.Kind==RepairInputKind.Sequence?actions==stage.Actions.Length&&shelf.Find("RepairHold")==null:actions==0&&shelf.Find("RepairHold")!=null,job.Id+" phase"+phase+" mode/count driven by workflow");foreach(var target in shelf.GetComponentsInChildren<Selectable>()){var r=UiMetrics.ScreenRect((RectTransform)target.transform);Check(r.width/3>=48.99f&&r.height/3>=48.99f,job.Id+pane+" repair target >=49 "+target.name);}}
  }
  typeof(RepairGame).GetField("<RepairOpen>k__BackingField",Private).SetValue(game,false);hud.Close();var car=new GameObject("UiBindingVehicle",typeof(Rigidbody),typeof(VehicleController));try{var vehicle=car.GetComponent<VehicleController>();typeof(VehicleController).GetMethod("Awake",Private).Invoke(vehicle,null);game.Vehicle=vehicle;var job=JobCatalog.Find("call-0-2");game.Profile.ActiveJob=job.Id;game.Profile.ActiveTicket=7;game.Profile.CompletedTicket=6;game.Profile.RepairPhase=2;car.transform.position=new Vector3(job.DestinationX,.11f,job.DestinationZ);Check(game.BeginRepair()&&game.Interaction.Stage==job.Presentation.Stages[2]&&game.Interaction.Kind==RepairInputKind.Sequence,language+pane+" actual BeginRepair binds active job's phase-two sequence");}finally{game.Vehicle=null;UnityEngine.Object.DestroyImmediate(car);}
  Check(game.Profile.Cash==2345&&game.Profile.Style==2,language+pane+" rendering/navigation retain wallet and selected paint");
 }finally{UnityEngine.Object.DestroyImmediate(canvasGo);UnityEngine.Object.DestroyImmediate(root);}}
 static void CheckFixedTargets(RectTransform modal,Vector2 pane){var bounds=UiMetrics.ScreenRect(modal);foreach(var hold in modal.GetComponentsInChildren<HoldButton>()){var r=UiMetrics.ScreenRect((RectTransform)hold.transform);Check(r.width/3>=48.99f&&r.height/3>=48.99f,pane+" actual Hold target >=49");Check(bounds.Contains(r.min)&&bounds.Contains(r.max),pane+" Hold remains inside pane");}foreach(var button in modal.GetComponentsInChildren<Button>()){if(button.transform.IsChildOf(modal.Find("PageBody")))continue;var r=UiMetrics.ScreenRect((RectTransform)button.transform);Check(r.width/3>=48.99f&&r.height/3>=48.99f,pane+" fixed target >=49 "+button.name);Check(r.xMin>=bounds.xMin-.5f&&r.xMax<=bounds.xMax+.5f&&r.yMin>=bounds.yMin-.5f&&r.yMax<=bounds.yMax+.5f,pane+" fixed target inside pane "+button.name);foreach(var text in button.GetComponentsInChildren<Text>())foreach(var state in new[]{button.colors.normalColor,button.colors.highlightedColor,button.colors.pressedColor,button.colors.selectedColor,button.colors.disabledColor})Check(Contrast(text.color,button.GetComponent<Image>().color*state)>=4.5f,pane+" button contrast >=4.5 "+button.name);}}
 static float Light(Color c){float Linear(float x)=>x<=.04045f?x/12.92f:Mathf.Pow((x+.055f)/1.055f,2.4f);return .2126f*Linear(c.r)+.7152f*Linear(c.g)+.0722f*Linear(c.b);}
 static float Contrast(Color a,Color b){float x=Light(a),y=Light(b);return (Mathf.Max(x,y)+.05f)/(Mathf.Min(x,y)+.05f);}
 static string IconSignature(Transform row){if(row==null)return "missing-row";foreach(var graphic in row.GetComponentsInChildren<Graphic>())if(!(graphic is Image)&&!(graphic is Text)&&!(graphic is RawImage)){using(var vertices=new VertexHelper()){graphic.GetType().GetMethod("OnPopulateMesh",Private,null,new[]{typeof(VertexHelper)},null).Invoke(graphic,new object[]{vertices});var mesh=new Mesh();try{vertices.FillMesh(mesh);long hash=17;foreach(var vertex in mesh.vertices)unchecked{hash=hash*31+Mathf.RoundToInt(vertex.x*100);hash=hash*31+Mathf.RoundToInt(vertex.y*100);}foreach(var color in mesh.colors32)unchecked{hash=hash*31+color.r;hash=hash*31+color.g;hash=hash*31+color.b;}return mesh.vertexCount+":"+hash;}finally{UnityEngine.Object.DestroyImmediate(mesh);}}}return "missing-icon";}
}
